'use strict';
let workbook={minutes:120,tasks:{},notes:{}};
try{const x=JSON.parse(localStorage.getItem('medico-workbook-v1')||'null');if(x&&typeof x==='object'){workbook.minutes=[60,120,180].includes(x.minutes)?x.minutes:120;for(const field of ['tasks','notes'])if(x[field]&&typeof x[field]==='object'&&!Array.isArray(x[field]))workbook[field]=x[field];}}catch{}
for(const [key,value] of Object.entries(workbook.tasks)){if(!/^\d+$/.test(key)||Number(key)<1||Number(key)>180||!Array.isArray(value))delete workbook.tasks[key];else workbook.tasks[key]=[...new Set(value.filter(id=>['review','read','explain','practice','reflect'].includes(id)))];}
for(const [key,value] of Object.entries(workbook.notes)){if(!/^(day:\d+|lesson:[a-z]+-\d+)$/.test(key)||typeof value!=='string')delete workbook.notes[key];else workbook.notes[key]=value.slice(0,6000);}
function saveWorkbook(){let message='Saved on this device.';try{localStorage.setItem('medico-workbook-v1',JSON.stringify(workbook));}catch{message='Storage unavailable. Copy your notes before leaving.';}const status=$('#workbook-status');if(status)status.textContent=message;}
function studyReadings(l){return (LESSON_TEXTBOOK_LINKS[l.id]||[]).map(t=>{const b=textbook(t.book);const next=b.chapters.filter(c=>c.page>t.page).sort((a,b)=>a.page-b.page)[0];return {...t,end:Math.min(t.page+7,next?next.page-1:b.pages),bookTitle:b.shortTitle};});}
function readingAssignment(l){const refs=studyReadings(l);if(refs.length)return refs.map((r,i)=>'<p><strong>'+(i?'Continue with: ':'Assigned reading: ')+'</strong><a href="#book/'+r.book+'/'+r.page+'">'+esc(r.title)+'</a> in '+esc(r.bookTitle)+', PDF pages '+r.page+'–'+r.end+'. Read this bounded passage first. Explain its main mechanism in your own words, redraw one available figure, and note any assumptions or exceptions before continuing into the rest of the chapter.</p>').join('');const ref=SUBJECT_REFERENCES.find(r=>r.subject===l.subject);return '<p>Begin with the explanation in this lesson, then use '+(ref?'<a href="'+esc(ref.url)+'" target="_blank" rel="noopener">'+esc(ref.title)+' from '+esc(ref.publisher)+'</a>':'the subject reference directory')+' to investigate this topic. This reference is a starting point; a dedicated full chapter for this lesson has not been imported. Record the source and section you actually read, and keep unanswered questions for a dedicated subject text.</p>';}
function lessonWorkbook(l){const g=SUBJECT_GUIDES[l.subject];return '<section class="lesson-workbook"><span class="eyebrow">STUDY THIS TOPIC IN DEPTH</span><h3>Read, explain, then apply</h3>'+readingAssignment(l)+'<h3>Reason through the subject</h3><p>'+esc(g.overview)+'</p><p>'+esc(g.task)+'</p><h3>Write an explanation without the notes</h3><p>Explain “'+esc(l.title)+'” using the sequence '+l.flow.map(esc).join(' → ')+'. For each connection, describe what changes and why the next step follows. Compare your account with the explanation above; correct the part you could name but could not explain.</p><h3>Check the underlying reasoning</h3>'+l.detail.map((t,i)=>'<details><summary>Reasoning check '+(i+1)+': explain this part of '+esc(l.title)+'</summary><p>'+esc(t)+'</p><p>Restate this idea without copying the sentence. Name the relationship being described and explain how it connects to '+esc(l.flow[Math.min(i,l.flow.length-1)])+'.</p></details>').join('')+'<details><summary>'+esc(l.q)+'</summary><p>'+esc(l.a)+'. '+esc(l.simple)+'</p></details><h3>Keep a study record</h3><label for="lesson-notes">Your explanation, source pages, and unresolved questions</label><textarea id="lesson-notes" data-workbook-note="lesson:'+l.id+'" maxlength="6000" rows="7" placeholder="Explain the mechanism in your own words. Record a mistake, its correction, and the question you still need to investigate.">'+esc(workbook.notes['lesson:'+l.id]||'')+'</textarea><p id="workbook-status" class="fine" role="status">Notes stay on this device.</p><button class="btn secondary" data-action="day" data-id="'+DAYS.find(d=>d.type==='learn'&&d.lessons.includes(l.id)).day+'">Open the scheduled study session</button></section>';}
function subjectProgramme(id){const s=subj(id),ds=DAYS.filter(d=>d.subject===id),g=SUBJECT_GUIDES[id];return '<section class="subject-programme panel"><span class="eyebrow">YOUR SUBJECT STUDY PROGRAMME</span><h2>How to work through '+esc(s.name)+'</h2><p>'+esc(g.overview)+' Study the lessons in the sequence below. Each session includes a reading assignment, an explanation you write yourself, and a check of what you can recall.</p><p>In the first pass, learn the language and explain the normal relationships before memorising isolated answers. '+esc(g.task)+' In the second pass, compare neighbouring topics and identify the assumptions that distinguish them. Finish with the collection’s connection and recall sessions, then revisit difficult explanations after one, seven, and twenty-one days.</p><div class="programme-sessions">'+ds.map(d=>'<article><span class="eyebrow">DAY '+d.day+' · '+(d.type==='learn'?'DEVELOP UNDERSTANDING':d.type==='map'?'CONNECT THE SUBJECT':'RETRIEVE AND CORRECT')+'</span><h3>'+esc(d.title)+'</h3><p>'+(d.type==='learn'?esc(lesson(d.lessons[0]).simple):d.type==='map'?'Build one coherent account that links the subject’s lessons. Annotate every connection with its reason, then compare it with the visual atlas.':'Answer the collection’s questions with the material closed. Review explanations only after writing your answers and record the errors to revisit.')+'</p><button class="btn secondary" data-action="day" data-id="'+d.day+'">Work through this session</button></article>').join('')+'</div></section>';}
function sessionTasks(d){const ls=d.lessons.map(lesson),first=ls[0],due=[1,7,21].map(gap=>DAYS[d.day-gap-1]).filter(Boolean).filter(x=>x.type==='learn');const names=ls.map(l=>l.title).join('; ');const ratio=workbook.minutes/120;const mins=[20,35,25,25,15].map(n=>Math.round(n*ratio));mins[4]+=workbook.minutes-mins.reduce((a,b)=>a+b,0);return [{id:'review',title:'Retrieve earlier material',minutes:mins[0],body:due.length?'Before opening today’s notes, answer the recall questions for '+due.map(x=>x.title+' (day '+x.day+')').join('; ')+'. These are the scheduled one-, seven-, and twenty-one-day returns. Check your answers afterwards and choose one error to correct today.':'Begin by writing what you already know about '+names+'. Mark guesses separately from explanations you can justify. At this point there is no earlier learning session due at the one-, seven-, or twenty-one-day interval.',lessons:due.flatMap(x=>x.lessons)}, {id:'read',title:d.type==='learn'?'Read the assigned passage':'Revisit the evidence and explanations',minutes:mins[1],body:d.type==='learn'?'Study '+first.title+' in the lesson and the assigned source passage below. Define unfamiliar language as it appears, connect the source figure to the mechanism, and stop at the reading boundary to explain what you have understood.':'Work through '+names+'. Read your previous notes before returning to the sources. Prioritise the topics you could not explain from memory rather than rereading every page.',lessons:d.lessons}, {id:'explain',title:d.type==='map'?'Build a connected subject explanation':'Write and draw the mechanism',minutes:mins[2],body:d.type==='learn'?'Write a connected account beginning with “'+first.flow[0]+'” and ending with “'+first.flow[first.flow.length-1]+'”. Explain each intermediate link. Then draw the relationship and use the subject exercise: '+SUBJECT_GUIDES[first.subject].task:'Connect '+ls.slice(0,3).map(l=>l.title).join(', ')+'. Explain how the concepts relate, where they differ, and which part of the relationship needs further evidence. Label the links in a diagram with reasons rather than single keywords.',lessons:[]},{id:'practice',title:'Answer, compare, and correct',minutes:mins[3],body:'Close the source and attempt the questions below in writing. Reveal the explanations only after answering. For each error, write what you believed, what the explanation establishes, and how you will recognise the distinction next time. These are concept checks; add reviewed exam questions separately when preparing for NEET PG.',lessons:[]},{id:'reflect',title:'Record the result and next reading',minutes:mins[4],body:'Save your own explanation and source page range in the session journal. Record one unresolved question and the specific reading needed to answer it. Mark the work you actually completed; schedule unfinished reading for your next available session.',lessons:[]}];}
function detailedDay(n){const d=DAYS[n-1];if(!d)return;const tasks=sessionTasks(d),checks=workbook.tasks[n]||[];showDialog('<div class="dialog-head"><div><span class="eyebrow">DAY '+n+' · '+esc(dateForDay(n)||'YOUR OWN PACE')+'</span><h2 id="lesson-title">'+esc(d.title)+'</h2></div><button class="close" data-action="close" aria-label="Close study day">×</button></div><div class="dialog-body detailed-session"><p>This is a '+workbook.minutes+'-minute session with a written result at the end. Use the reading boundaries as a first pass; difficult topics can continue across additional sessions.</p><p id="session-progress" class="notice">'+checks.filter(k=>tasks.some(t=>t.id===k)).length+' of 5 study blocks completed.</p>'+tasks.map((t,i)=>'<section class="session-block"><span class="eyebrow">'+String(i+1).padStart(2,'0')+' · '+t.minutes+' MINUTES</span><h3>'+esc(t.title)+'</h3><p>'+esc(t.body)+'</p>'+(t.id==='read'?d.lessons.map(id=>'<details '+(d.type==='learn'?'open':'')+'><summary>'+esc(lesson(id).title)+' — reading assignment</summary>'+readingAssignment(lesson(id))+'<button class="btn secondary" data-action="lesson" data-id="'+id+'">Open the complete lesson workspace</button></details>').join(''):t.id==='practice'?d.lessons.map(id=>{const l=lesson(id);return '<details><summary>'+esc(l.q)+'</summary><p>'+esc(l.a)+'. '+esc(l.simple)+'</p><p>'+esc(l.detail.join(' '))+'</p></details>';}).join(''):t.id==='review'?t.lessons.map(id=>'<button class="btn ghost" data-action="lesson" data-id="'+id+'">Review '+esc(lesson(id).title)+'</button>').join(''):'')+'<label class="session-check"><input type="checkbox" data-session-task="'+t.id+'" data-day="'+n+'" '+(checks.includes(t.id)?'checked':'')+'> I completed this study block</label></section>').join('')+'<section class="panel workbook-context"><h3>Extend your recall with source questions</h3><p>After the lesson checks, use the imported question bank. Try each question before its hint and source solution, then record what you need to revisit.</p><a class="btn secondary" href="#pyq">Open PYQ practice</a></section><section class="session-journal"><h3>Your session journal</h3><label for="day-notes">Explanation, corrected mistakes, source pages, and next steps</label><textarea id="day-notes" data-workbook-note="day:'+n+'" maxlength="6000" rows="8">'+esc(workbook.notes['day:'+n]||'')+'</textarea><p id="workbook-status" role="status" class="fine">Saved locally as you write.</p></section><div class="buttons"><button class="btn" data-action="day-complete" data-id="'+n+'">'+(saved.done.includes(n)?'Mark incomplete':'Mark day complete')+'</button><button class="btn secondary" data-action="export-journal">Download study journal</button></div></div>');}
function studyDashboard(){const next=DAYS.find(d=>!saved.done.includes(d.day))||DAYS[179];const entries=Object.keys(workbook.notes).filter(k=>String(workbook.notes[k]).trim()).length;return '<section class="study-dashboard panel"><span class="eyebrow">CONTINUE YOUR STUDY</span><h2>'+esc(next.title)+'</h2><p>'+saved.done.length+' of 180 days marked complete. Your next session includes assigned reading, a written explanation, recall practice and a saved journal. You have '+entries+' saved note entries.</p><div class="buttons"><button class="btn" data-action="day" data-id="'+next.day+'">Open day '+next.day+'</button><a class="btn secondary" href="#plan">View the detailed programme</a><button class="btn ghost" data-action="export-journal">Download your notes</button></div></section>';}
function journalLibrary(){const entries=Object.entries(workbook.notes).filter(([k,v])=>typeof v==='string'&&v.trim());return '<section class="panel journal-library"><h2>Your study journal</h2><p>Your explanations and session reflections are saved on this device. Export them regularly if you want a separate copy.</p>'+entries.map(([k,v])=>{const id=k.slice(k.indexOf(':')+1),isDay=k.startsWith('day:');const label=isDay?DAYS[Number(id)-1]?.title:lesson(id)?.title;if(!label)return '';return '<details><summary>'+esc(label)+'</summary><p class="journal-entry">'+esc(v)+'</p><button class="btn secondary" data-action="'+(isDay?'day':'lesson')+'" data-id="'+esc(id)+'">Continue this workspace</button></details>';}).join('')+(entries.length?'':'<p>Your journal will appear here after you write in a lesson or daily session.</p>')+'</section>';}
document.addEventListener('input',e=>{const key=e.target.dataset?.workbookNote;if(key&&/^(day:\d+|lesson:[a-z]+-\d+)$/.test(key)){workbook.notes[key]=e.target.value.slice(0,6000);saveWorkbook();}});
document.addEventListener('change',e=>{if(e.target.id==='study-minutes'){workbook.minutes=Number(e.target.value);if(![60,120,180].includes(workbook.minutes))workbook.minutes=120;saveWorkbook();plan();}const t=e.target.dataset?.sessionTask,n=Number(e.target.dataset?.day);if(t&&DAYS[n-1]&&sessionTasks(DAYS[n-1]).some(x=>x.id===t)){const items=Array.isArray(workbook.tasks[n])?workbook.tasks[n]:[];workbook.tasks[n]=e.target.checked?[...new Set([...items,t])]:items.filter(x=>x!==t);saveWorkbook();$('#session-progress').textContent=workbook.tasks[n].length+' of 5 study blocks completed.';}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button?.dataset.action==='export-journal'){const lines=['MEDICO STUDY JOURNAL','Exported '+new Date().toLocaleDateString(),''];for(const [key,value] of Object.entries(workbook.notes))if(typeof value==='string'&&value.trim())lines.push(key,value,'');const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='medico-study-journal.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});

function sectionStudyContext(route){const instructions={maps:['Use the atlas to explain a relationship','Study the selected diagram, then close it and reproduce the relationship with labels that explain the reason for each link. Compare your drawing with the diagram and the corresponding lesson. Record an incorrect connection in your lesson notes, then revisit it in the next recall session.'],resources:['Turn an image into a studied explanation','Read the image’s labels and source description together. Identify the structures or steps you can explain, then use the related lesson to connect them. Redraw the relevant part from memory and record the source with your explanation. An image alone does not establish the full mechanism.'],study:['Read a complete chapter in manageable sessions','Choose a textbook and a chapter, then read the bounded passage assigned by your lesson or study day. Pause to write a connected explanation before continuing. Use the original pages for equations, tables and diagrams; use search to locate terms and the saved reader position to return to your passage.'],sources:['Choose the source for the question you are studying','The imported textbooks supply complete chapters and original figures. The image references identify individual visual assets, and the subject directory offers additional external reading. Record the edition and section when you take notes; use the content scope to recognise subjects that still need a dedicated text.']};const data=instructions[route];if(!data)return '';return '<section class="workbook-context panel"><h2>'+data[0]+'</h2><p>'+data[1]+'</p><a class="btn secondary" href="#plan">Continue with your scheduled session</a></section>';}
